/**
 * The desk buttons' files (select-first/): Select first (picks a row of a native list), Go to
 * (opens another workspace) and Run action (runs a Global Smart Action), all styled by
 * select-first.css. Generated by scripts/build-public.js, through hub.js.
 */
const fs = require('fs');
const path = require('path');

const { COMPONENTS } = require('../paths');

const DIR = path.join(COMPONENTS, 'select-first');
const FILES = {
  'select-first.hbs': 'template.hbs',
  'select-first.js': 'component.js',
  'select-first.css': 'style.css',
};

/**
 * A file by name, or null. Besides Select first's own three, any .hbs, .js or .css of the folder
 * keeps its name (go-to, run-action, demo-guide…).
 */
function renderSelectFirstFile(name) {
  const source = FILES[name] || (/^[a-z-]+\.(hbs|js|css)$/.test(name) ? name : null);
  const file = source && path.join(DIR, source);

  return file && fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
}

module.exports = { renderSelectFirstFile };
